/**
 * 密度图标：同样高度里画几条横线，线越多越紧凑。
 * 不带外框，免得读成数据表格。
 */
function DensityIcon({ lines }: { lines: number }) {
  const top = 5
  const bottom = 19
  const step = (bottom - top) / (lines - 1)
  return (
    <svg
      data-slot="data-table-density-icon"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      aria-hidden="true"
      className="size-4"
    >
      {Array.from({ length: lines }, (_, i) => (
        <path key={i} d={`M4 ${top + step * i}h16`} />
      ))}
    </svg>
  )
}

function DataTableToolbar<T>({
  table,
  labels,
  density,
  onDensityChange,
  statusFilter,
  children,
  searchLabel,
  counts,
}: {
  table: Table<T>
  labels: DataTableLabels
  density: string
  onDensityChange: (value: string) => void
  statusFilter?: DataTableProps<T>["statusFilter"]
  counts?: Record<string, number>
  searchLabel?: React.ReactNode
  children?: React.ReactNode
}) {
  "use no memo"
  // Table v8 的对象引用稳定，子组件同样需要读取当前状态。
  const searchRef = React.useRef<HTMLInputElement>(null)
  React.useEffect(() => {
    function focusSearch(event: KeyboardEvent) {
      if (
        event.key !== "/" ||
        event.ctrlKey ||
        event.metaKey ||
        event.altKey ||
        (event.target instanceof HTMLElement &&
          (event.target.isContentEditable ||
            event.target.closest("input,textarea,select")))
      )
        return
      event.preventDefault()
      searchRef.current?.focus()
    }
    window.addEventListener("keydown", focusSearch)
    return () => window.removeEventListener("keydown", focusSearch)
  }, [])
  const statusColumn = statusFilter
    ? table.getColumn(statusFilter.columnId)
    : undefined
  const status = String(statusColumn?.getFilterValue() ?? "")
  // 格内的图标按钮：方形、无圆角，焦点环画在格子内侧
  const cellButton = "h-full rounded-none focus-visible:ring-inset"
  return (
    <GridToolbar
      bordered={false}
      // 表格工具栏统一 12px；触屏输入框保持 16px，避免 iOS 聚焦时页面放大
      className="[&_*]:text-xs! pointer-coarse:[&_input]:text-base!"
    >
      {/* 搜索：宽容器里定宽，窄容器里占满第一行 */}
      <GridToolbarItem
        grow
        className="@min-[40rem]:w-64 @min-[40rem]:flex-none"
      >
        <BarField
          label={searchLabel}
          aria-label={searchLabel ? undefined : labels.searchField}
          icon={<Search />}
          inputRef={searchRef}
          type="search"
          placeholder={labels.search}
          value={table.getState().globalFilter ?? ""}
          onValueChange={(value) => {
            table.setGlobalFilter(value)
            table.setPageIndex(0)
          }}
          suffix={
            <kbd className="pointer-events-none grid size-5 place-items-center rounded-sm border border-edge bg-muted font-mono text-[11px] text-muted-foreground pointer-coarse:hidden">
              /
            </kbd>
          }
        />
      </GridToolbarItem>
      {statusFilter && (
        // 状态筛选用方条下拉：清除即「全部」；窄容器里独占最后一行
        <GridToolbarItem className="order-last basis-full @min-[40rem]:order-none @min-[40rem]:w-36 @min-[40rem]:basis-auto">
          <BarSelect
            aria-label={labels.status}
            placeholder={
              statusFilter.options.find((option) => option.value === "")
                ?.label ?? labels.all
            }
            value={status || null}
            contentClassName="[&_*]:text-xs"
            options={statusFilter.options
              .filter((option) => option.value !== "")
              .map((option) => ({
                value: option.value,
                textValue: option.label,
                count: counts?.[option.value] ?? 0,
                label: (
                  <span className="flex items-center gap-2">
                    {option.tone && (
                      <span
                        aria-hidden="true"
                        className="size-1.5 shrink-0 rounded-full"
                        style={{ background: option.tone }}
                      />
                    )}
                    {option.label}
                  </span>
                ),
              }))}
            onValueChange={(value) => {
              statusColumn?.setFilterValue(value || undefined)
              table.setPageIndex(0)
            }}
          />
        </GridToolbarItem>
      )}
      {children}
      {/* 空白格：吃掉剩余宽度，让列设置与密度靠右 */}
      <GridToolbarItem
        grow
        aria-hidden="true"
        className="hidden @min-[40rem]:flex"
      />
      <GridToolbarItem>
        <DropdownMenu>
          <Tooltip>
            <TooltipTrigger
              render={
                <DropdownMenuTrigger
                  render={
                    <Button
                      variant="ghost"
                      size="icon-lg"
                      aria-label={labels.columns}
                      className={cellButton}
                    />
                  }
                />
              }
            >
              <Settings2 aria-hidden="true" />
            </TooltipTrigger>
            <TooltipContent>{labels.columns}</TooltipContent>
          </Tooltip>
          <DropdownMenuContent align="end" className="min-w-44 *:text-xs!">
            {table.getAllLeafColumns().map((column) => (
              <DropdownMenuCheckboxItem
                key={column.id}
                checked={column.getIsVisible()}
                onCheckedChange={(value) => column.toggleVisibility(value)}
                closeOnClick={false}
              >
                {String(column.columnDef.header ?? column.id)}
              </DropdownMenuCheckboxItem>
            ))}
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => table.resetColumnVisibility()}>
              {labels.reset}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </GridToolbarItem>
      {/* 密度是另一组：用实线与列设置分开；只用图标，文字在提示气泡和读屏里 */}
      <GridToolbarItem separator="solid" className="hidden @min-[40rem]:flex">
        <SegmentedControl
          aria-label={labels.density}
          iconOnly
          value={density}
          options={[
            {
              value: "40",
              label: labels.compact,
              icon: <DensityIcon lines={4} />,
            },
            {
              value: "52",
              label: labels.standard,
              icon: <DensityIcon lines={3} />,
            },
            {
              value: "64",
              label: labels.comfortable,
              icon: <DensityIcon lines={2} />,
            },
          ]}
          onValueChange={onDensityChange}
        />
      </GridToolbarItem>
      <GridToolbarItem className="@min-[40rem]:hidden">
        <DropdownMenu>
          <Tooltip>
            <TooltipTrigger
              render={
                <DropdownMenuTrigger
                  render={
                    <Button
                      size="icon-lg"
                      variant="ghost"
                      aria-label={labels.sort}
                      className={cellButton}
                    />
                  }
                />
              }
            >
              <ArrowUpDown aria-hidden="true" />
            </TooltipTrigger>
            <TooltipContent>{labels.sort}</TooltipContent>
          </Tooltip>
          <DropdownMenuContent align="end" className="*:text-xs!">
            {table
              .getAllLeafColumns()
              .filter((column) => column.getCanSort())
              .map((column) => (
                <React.Fragment key={column.id}>
                  {[false, true].map((desc) => (
                    <DropdownMenuItem
                      key={String(desc)}
                      onClick={() => column.toggleSorting(desc)}
                    >
                      {String(column.columnDef.header)} ·{" "}
                      {desc ? labels.descending : labels.ascending}
                    </DropdownMenuItem>
                  ))}
                </React.Fragment>
              ))}
          </DropdownMenuContent>
        </DropdownMenu>
      </GridToolbarItem>
    </GridToolbar>
  )
}
